{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 미등록 모임이 활동 내용만 같으면 자전거이용민간단체에 해당하는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제2조제9호는 자전거이용민간단체를 자전거이용 환경개선과 자전거이용의 저변확대 등을 주요사업으로 하면서 「비영리민간단체지원법」 제4조 규정에 따라 서울특별시에 등록된 단체로 정의한다. 따라서 활동 내용이 같더라도 서울시에 등록하지 않은 모임은 조례에서 정의한 자전거이용민간단체에 해당하지 않는다.",
          "b_ids": "자전거:제2조제9호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
